// ─── Schema Addition ──────────────────────────────────────────────────────────

async function addSchemaColumns(): Promise<void> {
  // duty_export column
  await db.execute(sql`
    ALTER TABLE btki_tariff ADD COLUMN IF NOT EXISTS duty_export NUMERIC DEFAULT 0
  `).catch(() => {});
  // ftas stored separately as a JSONB convenience column
  await db.execute(sql`
    ALTER TABLE btki_tariff ADD COLUMN IF NOT EXISTS ftas JSONB
  `).catch(() => {});
  // chapter/heading/subheading as generated columns or stored text for fast lookup
  await db.execute(sql`
    ALTER TABLE btki_tariff ADD COLUMN IF NOT EXISTS chapter TEXT GENERATED ALWAYS AS (
      SUBSTRING(REPLACE(hs_code, '.', ''), 1, 2)
    ) STORED
  `).catch(() => {}); // idempotent — ignore if exists
  await db.execute(sql`
    CREATE INDEX IF NOT EXISTS btki_chapter_idx ON btki_tariff(chapter)
  `).catch(() => {});
  await db.execute(sql`
    CREATE INDEX IF NOT EXISTS btki_fts_en_idx ON btki_tariff USING gin(to_tsvector('simple', COALESCE(description_en, '')))
  `).catch(() => {});
}

// ─── Runner ───────────────────────────────────────────────────────────────────

export async function runBtkiSupplementalSeed(): Promise<void> {
  try {
    await addSchemaColumns();

    logger.info({ toInsert: SUPPLEMENT.length }, "[btki] Running supplemental BTKI seed (upsert)...");

    let ok = 0;
    let skip = 0;

    for (const row of SUPPLEMENT) {
      const hs = row.hs_code.replace(/\./g, "");
      const hs6 = hs.slice(0, 6);
      const hs4 = hs.slice(0, 4);
      const hs2 = hs.slice(0, 2);

      const ftasJson = (() => {
        const obj: Record<string, number> = {};
        if (row.bm_acfta !== undefined) obj["ACFTA"] = row.bm_acfta;
        if (row.bm_afta !== undefined) obj["AFTA"] = row.bm_afta;
        if (row.bm_aifta !== undefined) obj["AIFTA"] = row.bm_aifta;
        if (row.bm_aanzfta !== undefined) obj["AANZFTA"] = row.bm_aanzfta;
        if (row.bm_ahkfta !== undefined) obj["AHKFTA"] = row.bm_ahkfta;
        return Object.keys(obj).length ? JSON.stringify(obj) : null;
      })();

      await db.execute(sql`
        INSERT INTO btki_tariff (
          hs_code, hs_code_6, hs_code_4, hs_code_2,
          description_id, description_en, unit,
          bm_mfn, bm_acfta, bm_afta, bm_aifta, bm_aanzfta, bm_ahkfta,
          ppn_rate, ppnbm_rate, pph22_rate, pph22_non_api,
          lartas_import, lartas_export, lartas_desc,
          regulator_import, regulator_export,
          perizinan_import,
          notes, category, ftas
        ) VALUES (
          ${row.hs_code}, ${hs6}, ${hs4}, ${hs2},
          ${row.description_id}, ${row.description_en ?? null}, ${row.unit ?? null},
          ${row.bm_mfn}, ${row.bm_acfta ?? null}, ${row.bm_afta ?? null},
          ${row.bm_aifta ?? null}, ${row.bm_aanzfta ?? null}, ${row.bm_ahkfta ?? null},
          ${row.ppn_rate ?? 11}, ${row.ppnbm_rate ?? 0}, ${row.pph22_rate ?? 2.5}, 7.5,
          ${row.lartas_import ?? false}, ${row.lartas_export ?? false},
          ${row.lartas_desc ?? null},
          ${row.regulator_import ?? null}, ${row.regulator_export ?? null},
          ${row.perizinan_import ? JSON.stringify(row.perizinan_import) : null},
          ${row.notes ?? null}, ${row.category}, ${ftasJson}
        )
        ON CONFLICT (hs_code) DO UPDATE SET
          description_id   = EXCLUDED.description_id,
          description_en   = EXCLUDED.description_en,
          bm_mfn           = EXCLUDED.bm_mfn,
          bm_acfta         = EXCLUDED.bm_acfta,
          bm_afta          = EXCLUDED.bm_afta,
          ppn_rate         = EXCLUDED.ppn_rate,
          ppnbm_rate       = EXCLUDED.ppnbm_rate,
          pph22_rate       = EXCLUDED.pph22_rate,
          lartas_import    = EXCLUDED.lartas_import,
          lartas_export    = EXCLUDED.lartas_export,
          lartas_desc      = EXCLUDED.lartas_desc,
          regulator_import = EXCLUDED.regulator_import,
          perizinan_import = EXCLUDED.perizinan_import,
          category         = EXCLUDED.category,
          ftas             = EXCLUDED.ftas,
          notes            = EXCLUDED.notes,
          updated_at       = NOW()
      `).then(() => ok++).catch((e) => {
        logger.warn({ hs_code: row.hs_code, err: String(e) }, "[btki] supplement row failed");
        skip++;
      });
    }

    logger.info({ ok, skip, total: SUPPLEMENT.length }, "[btki] Supplemental BTKI seed complete");
  } catch (err) {
    logger.error({ err }, "[btki] Supplemental seed failed");
    throw err;
  }
}
